"function draw() {
    var slot = el('sysUpdateAction');
    if (!slot) return;
    slot.innerHTML = (_caps.permitted && _upd.latest)
      ? '<button class="sbtn sbtn-warn" id="sysUpdateBtn" style="padding:.1rem .45rem;font-size:.64rem">Update</button>'
      : '';
  }"
